package com.intermarche.backoffice.engine.fieldops;
import static com.intermarche.backoffice.domain.fieldops.FieldEntityIds.id;
import com.intermarche.backoffice.domain.policy.OperationalPolicyVersion;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.order.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.engine.policy.OperationalPolicySchemas;import com.intermarche.backoffice.engine.stock.InventoryCountMath;import com.intermarche.backoffice.engine.operator.OperatorFailure;import com.intermarche.backoffice.rules.RuleSchemaRegistry;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import jakarta.transaction.Transactional;import jakarta.ws.rs.*;import java.util.*;import java.math.BigDecimal;
@ApplicationScoped @Transactional public class OperationalPolicyService {
 @Inject FieldOperationsService field;@Inject StockCommands receipts;@Inject ObjectMapper mapper;@Inject RuleSchemaRegistry registry;@Inject TraceabilityService trace;@Inject InventoryCountingService inventory;@Inject ParcelService parcels;@Inject OperationalPolicyVersions versions;
 @org.eclipse.microprofile.openapi.annotations.media.Schema(name="OperationalPolicyInput") public static class Input {public Long storeId;public String requestKey,expectedRevision,simulationToken,reason;public JsonNode specification,testCase;}
 private ObjectNode normalize(Store store,JsonNode raw){if(raw==null||!raw.isObject())throw new BadRequestException("Paramètres requis");String kind=raw.path("type").asText();ObjectNode value;try{value=OperationalPolicySchemas.defaults(kind);raw.fields().forEachRemaining(e->value.set(e.getKey(),e.getValue()));registry.validate(OperationalPolicySchemas.CATEGORY,value,List.of(store));}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}value.remove(List.of("id","priority"));if("TraceabilityConstraints".equals(kind)){Product p=Product.findById(value.path("productId").asLong());if(p==null||!p.active)throw new BadRequestException("Choisissez un produit actif");if(value.path("serialRequired").asBoolean()&&p.productType!=ProductType.UNIT)throw new BadRequestException("Les numéros de série exigent un produit géré à l’unité");}for(String key:List.of("absoluteTolerance","relativeTolerancePercent","maximumWeightKg"))if(value.hasNonNull(key)&&value.path(key).decimalValue().scale()>(key.equals("relativeTolerancePercent")?4:6))throw new BadRequestException("Précision trop élevée : "+key);if("CateringConstraints".equals(kind)){try{com.intermarche.backoffice.engine.catering.CateringReferentialValidation.maxAdvanceHours(value.path("maxAdvanceHours").asInt(),value.path("shelfLifeHours").asInt());}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}}return value;}
 private OperationalPolicyVersion active(Store store,JsonNode spec){return OperationalPolicyVersion.find("store=?1 and scopeKey=?2 and active=true",store,OperationalPolicySchemas.scope(spec)).firstResult();}
 private ObjectNode currentValues(Store store,String kind,Long productId,String context){var value=OperationalPolicySchemas.defaults(kind);if("InventoryConstraints".equals(kind))value.setAll((ObjectNode)mapper.valueToTree(inventory.control(store)));else if("ParcelConstraints".equals(kind)){ObjectNode p=mapper.valueToTree(parcels.readPolicy(store.id));p.remove("revision");value.setAll(p);}else if("TraceabilityConstraints".equals(kind)){value.put("context",context==null?"PICKING":context);if(productId!=null){Product p=Product.findById(productId);if(p==null||!p.active)throw new BadRequestException("Produit actif requis");value.put("productId",productId);TraceabilityPolicy policy=TraceabilityPolicy.find("store=?1 and product=?2 and context=?3",store,p,value.path("context").asText()).firstResult();if(policy!=null){value.put("lotRequired",policy.lotRequired).put("serialRequired",policy.serialRequired).put("dateRequired",policy.dateRequired).put("minimumRemainingDays",policy.minimumRemainingDays).put("bestBeforeStrict",policy.bestBeforeStrict).put("allocationMethod",policy.allocationMethod).put("hazardClass",policy.hazardClass==null?"":policy.hazardClass).put("separationGroup",policy.separationGroup==null?"":policy.separationGroup).put("incompatibleHazards",policy.incompatibleHazards==null?"":policy.incompatibleHazards);}}}else value=(ObjectNode)OperationalPolicyVersions.active(store,kind);return value;}
 private String revision(Store store,JsonNode specification){String kind=specification.path("type").asText();Long product=specification.hasNonNull("productId")?specification.path("productId").asLong():null;var values=currentValues(store,kind,product,specification.path("context").asText(null));var latest=active(store,values);return field.hash(Arrays.asList(values,latest==null?0:latest.revisionNumber));}
 public Object catalog(Long storeId){Store s=field.store(storeId,false);return Map.of("storeId",s.id,"canManage",field.manager(),"definitions",OperationalPolicySchemas.definitions().stream().map(d->Map.of("type",d.type(),"label",d.label(),"schema",field.decode(d.schema(),Map.class),"defaults",OperationalPolicySchemas.defaults(d.type()),"testCase",example(d.type()))).toList(),"constraints",List.of("Une politique encadre une exécution ; elle ne crée pas de mission.","Blocages qualité, DLC expirées, séparation des températures et droits restent obligatoires.","La simulation utilise un scénario de test, sans modifier les stocks."));}
 public Object current(Long storeId,String kind,Long productId,String context){Store s=field.store(storeId,false);try{OperationalPolicySchemas.schema(kind);}catch(IllegalArgumentException e){throw new BadRequestException(e.getMessage());}if(context!=null&&!Set.of("RECEIPT","PICKING","SHIPPING","RETURN").contains(context))throw new BadRequestException("Contexte inconnu");var values=currentValues(s,kind,productId,context);String key=OperationalPolicySchemas.scope(values);var history=OperationalPolicyVersion.<OperationalPolicyVersion>find("store=?1 and scopeKey=?2 order by revisionNumber desc",s,key).range(0,49).list().stream().map(this::view).toList();return Map.of("values",values,"revision",revision(s,values),"history",history,"canManage",field.manager());}
 private Map<String,Object> view(OperationalPolicyVersion version){var v=new LinkedHashMap<String,Object>();v.put("id",version.id);v.put("version",version.revisionNumber);v.put("active",version.active);v.put("activatedAt",version.createdAt);v.put("activatedBy",version.activatedBy);v.put("reason",version.reason);v.put("specification",field.decode(version.specification,Map.class));v.put("simulation",version.simulation==null?null:field.decode(version.simulation,Map.class));return v;}
 public Object simulate(Input input){if(input==null)throw new BadRequestException();Store s=field.store(input.storeId,false);field.requireManager();var spec=normalize(s,input.specification);String current=revision(s,spec);if(!Objects.equals(input.expectedRevision,current))throw new OperatorFailure(409,"STALE_OPERATIONAL_POLICY","Les paramètres actifs ont changé. Actualisez avant de simuler.");var result=evaluate(spec,input.testCase);return Map.of("result",result,"simulationToken",field.hash(Arrays.asList(s.id,field.actor(),spec,input.testCase,current)),"specification",spec,"revision",current,"testOnly",true);}
 public Object activate(Input input){if(input==null)throw new BadRequestException();Store s=field.store(input.storeId,true);field.requireManager();FieldOperationsService.key(input.requestKey);String fp=field.hash(input);var prior=receipts.previous(s,input.requestKey,fp);if(prior!=null)return receipts.value(prior);var spec=normalize(s,input.specification);String rev=revision(s,spec);if(!Objects.equals(input.expectedRevision,rev))throw new OperatorFailure(409,"STALE_OPERATIONAL_POLICY","La politique a changé. Actualisez puis relancez la simulation.");var simulated=evaluate(spec,input.testCase);if(!Objects.equals(input.simulationToken,field.hash(Arrays.asList(s.id,field.actor(),spec,input.testCase,rev))))throw new OperatorFailure(409,"POLICY_SIMULATION_REQUIRED","Simulez cette version et ce scénario avant de l’activer.");FieldOperationsService.text(input.reason,500);String kind=spec.path("type").asText();String childKey="policy-"+field.hash(Arrays.asList(input.requestKey,kind)).substring(0,48);
  if("TraceabilityConstraints".equals(kind)){var p=mapper.convertValue(withoutMeta(spec),TraceabilityService.Input.class);p.storeId=s.id;TraceabilityPolicy actual=TraceabilityPolicy.find("store=?1 and product.id=?2 and context=?3",s,p.productId,p.context).firstResult();p.expectedRevision=actual==null?null:field.hash(Arrays.asList(actual.id,actual.version));trace.savePolicy(p);}
  else if("InventoryConstraints".equals(kind)){var p=mapper.convertValue(withoutMeta(spec),InventoryCountingService.PolicyInput.class);p.storeId=s.id;p.requestKey=childKey;@SuppressWarnings("unchecked")var current=(Map<String,Object>)inventory.policy(s.id);p.expectedRevision=current.get("revision").toString();inventory.savePolicy(p);}
  else if("ParcelConstraints".equals(kind)){var p=mapper.convertValue(withoutMeta(spec),ParcelService.PolicyInput.class);p.storeId=s.id;p.requestKey=childKey;@SuppressWarnings("unchecked")var current=(Map<String,Object>)parcels.readPolicy(s.id);p.expectedRevision=((Number)current.get("revision")).intValue();parcels.savePolicy(p);}
  else versions.record(s,kind,spec,input.reason);
  var activated=active(s,spec);activated.reason=input.reason;activated.specification=field.encode(spec);activated.simulation=field.encode(Map.of("testCase",input.testCase,"result",simulated,"testOnly",true));field.flush();return receipts.record(s,input.requestKey,fp,"ACTIVATE_OPERATIONAL_POLICY",current(s.id,kind,spec.hasNonNull("productId")?spec.path("productId").asLong():null,spec.path("context").asText(null)));
 }
 private ObjectNode withoutMeta(ObjectNode spec){var copy=spec.deepCopy();copy.remove(List.of("type","name","id","priority"));return copy;}
 static JsonNode example(String type){var n=new ObjectMapper().createObjectNode();return switch(type){case"TraceabilityConstraints"->n.put("hasLot",true).put("hasSerial",true).put("hasDate",true).put("remainingDays",10).put("expired",false).put("quality","AVAILABLE").put("dateKind","DLC");case"InventoryConstraints"->n.put("reference",10).put("observed",9).put("movements",0).put("known",true);case"ApprovalConstraints"->n.put("action","RETURN_ITEM").put("differentApprover",true).put("elapsedMinutes",5);case"SupportConstraints"->n.put("kind","TOTE").put("volumeLiters",12).put("capacityLiters",30).put("weightKg",8).put("capacityWeightKg",25).put("compatibleTemperature",true).put("foodSeparated",true);case"ConsultationConstraints"->n.put("view","ACTIVITY");case"ParcelConstraints"->n.put("hasWeight",true).put("hasDimensions",true).put("contentConfirmed",true).put("scanMatches",true);case"CateringConstraints"->n;default->throw new BadRequestException("Politique inconnue");};}
 private BigDecimal decimal(JsonNode sample,String key){if(!sample.hasNonNull(key)||!sample.path(key).isNumber())throw new BadRequestException("Valeur numérique de test requise : "+key);BigDecimal value=sample.path(key).decimalValue();if(value.abs().compareTo(new BigDecimal("1000000000"))>0||value.scale()>6)throw new BadRequestException("Quantité de test trop grande ou trop précise");return value;}
 private Object evaluate(JsonNode spec,JsonNode sample){if(sample==null||!sample.isObject()||sample.toString().length()>4000)throw new BadRequestException("Scénario de test requis");String type=spec.path("type").asText();var example=example(type);var keys=sample.fieldNames();while(keys.hasNext())if(!example.has(keys.next()))throw new BadRequestException("Paramètre de test inconnu");for(var entries=example.fields();entries.hasNext();){var e=entries.next();if(!sample.has(e.getKey())||e.getValue().isBoolean()&&!sample.path(e.getKey()).isBoolean()||e.getValue().isTextual()&&!sample.path(e.getKey()).isTextual())throw new BadRequestException("Scénario incomplet ou mal typé : "+e.getKey());}
  for(String key:List.of("reference","observed","elapsedMinutes","volumeLiters","capacityLiters","weightKg","capacityWeightKg"))if(sample.has(key)&&decimal(sample,key).signum()<0)throw new BadRequestException("Valeur de test négative interdite : "+key);
  var reasons=new ArrayList<String>();switch(type){
   case"TraceabilityConstraints"->{if(!com.intermarche.backoffice.engine.stock.StockEligibility.qualityAllowed(sample.path("quality").asText()))reasons.add("La qualité du lot interdit son utilisation");if(!Set.of("DLC","DDM").contains(sample.path("dateKind").asText()))throw new BadRequestException("Date de test : DLC ou DDM");for(String flag:List.of("Lot","Serial","Date"))if(spec.path(flag.toLowerCase()+"Required").asBoolean()&&!sample.path("has"+flag).asBoolean())reasons.add("Identification obligatoire absente : "+flag);var now=com.intermarche.backoffice.domain.util.DateTimeProvider.now();var days=decimal(sample,"remainingDays");if(days.scale()>0&&days.stripTrailingZeros().scale()>0)throw new BadRequestException("Un nombre entier de jours est requis");var date=sample.path("hasDate").asBoolean()?now.toLocalDate().plusDays(sample.path("expired").asBoolean()?-1:days.longValueExact()):null;if(sample.path("expired").asBoolean()&&date==null)throw new BadRequestException("Une date expirée doit être renseignée");boolean useBy="DLC".equals(sample.path("dateKind").asText());if(!com.intermarche.backoffice.engine.stock.StockEligibility.dateAllowed(now,useBy?date:null,useBy?null:date,spec.path("minimumRemainingDays").asInt(),spec.path("bestBeforeStrict").asBoolean()))reasons.add("La date ne couvre pas la durée restante exigée");}
   case"InventoryConstraints"->{if(!sample.path("known").asBoolean())reasons.add("Quantité inconnue : recomptage ou arbitrage requis");else{var comparison=InventoryCountMath.compare(decimal(sample,"reference"),decimal(sample,"observed"),decimal(sample,"movements"),BigDecimal.ZERO,spec.path("absoluteTolerance").decimalValue(),spec.hasNonNull("relativeTolerancePercent")?spec.path("relativeTolerancePercent").decimalValue():null);if(comparison.recountRequired())reasons.add("L’écart dépasse les tolérances : recomptage ou arbitrage requis");}}
   case"ApprovalConstraints"->{boolean allowed=false;for(var a:spec.path("allowedActions"))if(a.asText().equals(sample.path("action").asText()))allowed=true;if(!allowed)reasons.add("Correction non autorisée par cette politique");if(!sample.path("differentApprover").asBoolean())reasons.add("Un autre responsable doit approuver");if(decimal(sample,"elapsedMinutes").compareTo(spec.path("expiryMinutes").decimalValue())>=0)reasons.add("Approbation périmée");}
   case"SupportConstraints"->{boolean allowed=false;for(var k:spec.path("allowedKinds"))if(k.asText().equals(sample.path("kind").asText()))allowed=true;if(!allowed)reasons.add("Type de support non autorisé");var volume=decimal(sample,"capacityLiters").multiply(spec.path("maximumFillPercent").decimalValue()).divide(BigDecimal.valueOf(100));if(decimal(sample,"volumeLiters").compareTo(volume)>0)reasons.add("Le volume dépasse le remplissage autorisé");var weight=decimal(sample,"capacityWeightKg");if(spec.hasNonNull("maximumWeightKg"))weight=weight.min(spec.path("maximumWeightKg").decimalValue());if(decimal(sample,"weightKg").compareTo(weight)>0)reasons.add("Poids maximal dépassé");if(!sample.path("compatibleTemperature").asBoolean()||!sample.path("foodSeparated").asBoolean())reasons.add("Séparation alimentaire/température obligatoire");}
   case"ConsultationConstraints"->{String view=sample.path("view").asText();if(!Set.of("ACTIVITY","COMMAND_HISTORY","PREVIOUS_INSTRUCTIONS").contains(view))throw new BadRequestException("Vue de consultation inconnue");String flag=switch(view){case"ACTIVITY"->"showOwnActivity";case"COMMAND_HISTORY"->"showCommandHistory";default->"showPreviousProductInstructions";};if(!spec.path(flag).asBoolean())reasons.add("Cet historique est masqué pour le préparateur");}
   case"ParcelConstraints"->{for(String[] flags:List.of(new String[]{"requireWeight","hasWeight","Poids réel absent"},new String[]{"requireDimensions","hasDimensions","Dimensions absentes"},new String[]{"requireContentConfirmation","contentConfirmed","Contenu non confirmé"},new String[]{"requireScan","scanMatches","Scan absent ou incorrect"}))if(spec.path(flags[0]).asBoolean()&&!sample.path(flags[1]).asBoolean())reasons.add(flags[2]);}
   case"CateringConstraints"->{/* Static execution constraints: no mission scenario to evaluate. */}
   default->throw new BadRequestException();
  }return Map.of("allowed",reasons.isEmpty(),"reasons",reasons,"message",reasons.isEmpty()?"Ce scénario respecte les contraintes.":"Ce scénario demande une correction ou un contrôle.");
 }
}
